import React, { useState, useRef, useLayoutEffect, useEffect, useContext, Suspense } from "react";
import { visStyle } from "./visitorColor";
import { receiptTone } from "./cmdReceipt";
import { parseMcpResult } from "./feedRows";
import ServiceContext from "../../ServiceContext";
import lazyLoad from "../../utils/lazyLoad";
import SpeakReply from "../../molecules/SpeakReply/SpeakReply";
import "./styles.scss";

// THE RUN IS A HANDLE, DISPLAYED (his design: "we have a handle on it and we display it" — no
// files, no plugin writes, nothing to maintain). runTests holds its result in hub memory under a
// short id; opening the row fetches it once and renders the REAL saved-test display (the same
// TestPane the Test Panel and docs use), hydrated with the results in hand. Expired handle (hub
// restarted, or 20 runs later) → the text result still stands, nothing lost.
const TestPaneLazy = lazyLoad(() => import("../Stage/TestPane"));

// RFC-046 — THE FEED ITSELF, with no chrome around it, because it has to sit in two places: the
// agent's CHAT (where he actually talks to us, and where the silence between messages is the thing
// he complained about) and a standalone pane. His correction, when I built the pane first:
// *"there's a new agent in a section in a navigation, and that's not what I meant by anything I
// said"* — he said he does not see the agents work IN THE CONVERSATIONS. So this component owns the
// rows and nothing else; whoever mounts it owns the header, the input and the arrangement.
export const CLASSNAME = "agent-wb";

// DO NOT BUILD A RUNNING COST METER ON THIS NUMBER. Measured on the wire by autobot over a live
// 3-turn session (2026-08-24): `total_cost_usd` on subscription hosting was 0 on turn one and then
// FROZEN at 0.000941 across turns two and three — neither per-turn nor cleanly cumulative, it simply
// stops moving. So this is a per-turn footnote on a receipt that already says what it is, and that
// is the only weight it can carry; a header meter reading "$" beside the context bar would be the
// fourth meter lie of the same day. `num_turns` beside it WAS measured trustworthy — 1 on every
// result, per-turn, not cumulative — which is what makes "only the receipt pays" (feedRows) a
// structural discriminator rather than a lucky one. Anyone wanting real money: re-measure on a
// Console/API-key session first, and say on the face of it which one you measured.
const money = (n) => (typeof n === "number" && n > 0 ? `$${n < 0.01 ? n.toFixed(4) : n.toFixed(2)}` : "");

// WHEN, next to every turn — his ask: *"I need to see a timestamp next to the chats."* Today's
// messages carry just the clock; older ones say the day too, because a resumed conversation
// replays yesterday and "3:41 PM" alone would lie about which yesterday.
export const timeOf = (ts) => {
  if (!ts) return "";
  const d = new Date(ts);
  if (isNaN(d.getTime())) return "";
  const hm = d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  return d.toDateString() === new Date().toDateString() ? hm : `${d.getMonth() + 1}/${d.getDate()} ${hm}`;
};
const When = ({ ts }) => (ts ? <span className={`${CLASSNAME}__ts`}>{timeOf(ts)}</span> : null);

// A COMMAND FOLDS AWAY BY DEFAULT. I opened them first — he asked for that — and then saw it and
// said the opposite: *"my bad, don't make the commands open by default, way better closed in this
// scenario."* He is right, and it is obvious once you look: a chat is a conversation with receipts
// in it, and a receipt that unrolls itself buries the sentence it belongs to.
//
// AND CLOSING IS THE SAME CONTROL THAT OPENED IT — *"why the fuck would you make them not
// closeable?"* My fold sign only appeared on hover, so it read as expand-only. The whole header is
// the toggle now, and the sign is always visible, because a control you cannot see is a control
// that is not there.


// JSON, DISTINGUISHED — his ask: the call's input read as a flat grey dump. A tiny tokenizer
// colors keys, string values, numbers and punctuation so it looks like an object, not stdout. No
// library (CSP), no font-size change — just color, which is what "distinguished" meant.
const HiJson = ({ value }) => {
  const text = JSON.stringify(value, null, 2);
  const re = /("(?:\\.|[^"\\])*")(\s*:)?|(\btrue\b|\bfalse\b|\bnull\b)|(-?\d+(?:\.\d+)?)|([{}\[\],])/g;
  const parts = [];
  let last = 0;
  let m;
  let i = 0;
  while ((m = re.exec(text))) {
    if (m.index > last) parts.push(text.slice(last, m.index));
    if (m[1]) {
      parts.push(<span key={i++} className={`agent-wb__json-${m[2] ? "key" : "str"}`}>{m[1]}</span>);
      if (m[2]) parts.push(<span key={i++} className="agent-wb__json-punc">{m[2]}</span>);
    } else if (m[3]) {
      parts.push(<span key={i++} className="agent-wb__json-lit">{m[3]}</span>);
    } else if (m[4]) {
      parts.push(<span key={i++} className="agent-wb__json-num">{m[4]}</span>);
    } else if (m[5]) {
      parts.push(<span key={i++} className="agent-wb__json-punc">{m[5]}</span>);
    }
    last = re.lastIndex;
  }
  if (last < text.length) parts.push(text.slice(last));
  return <pre className="agent-wb__blk agent-wb__blk--args agent-wb__json">{parts}</pre>;
};

const Block = ({ kind, children }) => (
  <pre className={`${CLASSNAME}__blk ${CLASSNAME}__blk--${kind}`}>{children}</pre>
);

const TestRunEmbed = ({ project, runId, output, failed }) => {
  const { SystemViewService } = useContext(ServiceContext);
  const [run, setRun] = useState(undefined); // undefined = fetching, null = expired
  useEffect(() => {
    let live = true;
    (async () => {
      try {
        const CLI = SystemViewService && SystemViewService.CLI;
        const r = CLI && CLI.getRun ? await CLI.getRun({ id: runId }) : null;
        if (live) setRun(r && !r.expired && Array.isArray(r.tests) ? r : null);
      } catch {
        if (live) setRun(null);
      }
    })();
    return () => { live = false; };
  }, [runId, SystemViewService]);
  const textBlock = <Block kind={failed ? "err" : "out"}>{output}</Block>;
  if (run === undefined) return textBlock;
  if (!run) return textBlock; // the handle aged out — the words remain
  const seen = new Set();
  const targets = [];
  for (const t of run.tests || []) {
    const key = `${t.serviceId}.${t.moduleName}.${t.methodName}`;
    if (!seen.has(key)) {
      seen.add(key);
      targets.push({ serviceId: t.serviceId, moduleName: t.moduleName, methodName: t.methodName, key });
    }
  }
  return (
    <div className={`${CLASSNAME}__runpanes`}>
      <Suspense fallback={textBlock}>
        {targets.map((t) => (
          <TestPaneLazy key={t.key} target={t} projectCode={project} ranData={run} />
        ))}
      </Suspense>
    </div>
  );
};

// A MESSAGE TO ANOTHER AGENT READS LIKE A MESSAGE — his rule: inter-agent traffic must be
// followable in the chat after the fact, whatever mechanism carried it. Who it went to on the
// header line, the words themselves on screen below it — never folded behind a click, because
// "follow the conversation" means reading it, not excavating it. The reply comes back as a named
// visitor row, so the two directions read as one thread.
const SentRow = ({ row }) => (
  <div className={`${CLASSNAME}__row ${CLASSNAME}__row--tool ${CLASSNAME}__row--sent ${CLASSNAME}__row--${row.state}`}>
    <When ts={row.ts} />
    <div className={`${CLASSNAME}__tool-head`}>
      <span className={`${CLASSNAME}__dot ${CLASSNAME}__dot--${row.state}`} />
      <span className={`${CLASSNAME}__tool-sum`}>
        <span className={`${CLASSNAME}__sent-kind`}>message</span>
        <span className={`${CLASSNAME}__sent-to`}>→ {row.xsend.to}</span>
        {row.xsend.about && <span className={`${CLASSNAME}__sent-about`}>{row.xsend.about}</span>}
      </span>
    </div>
    {/* THE SAME MEASURED FOLD HIS OWN LONG MESSAGES GET — his catch, the day this row shipped:
        a long briefing to another agent is a wall exactly like "my long ass chat", and it was
        bypassing the clamp. Short messages stay exactly as they are; only a body that genuinely
        runs past the line grows a See more. */}
    {row.xsend.msg && (
      <div className={`${CLASSNAME}__sent-body`}>
        <Said row={{ text: row.xsend.msg }} clamp />
      </div>
    )}
  </div>
);

// A PROBE OPENS AS A RUN. `systemview probe Service.Module.method '{…}'` is a method call, and
// the document vocabulary already has the block for one: an ad-hoc `:::run` with that step. So an
// opened probe row draws the same runnable the docs use instead of a "code" button pointed at a
// namespace as if it were a file (his catch). THE RESULT RIDES IN: the probe already ran and
// printed its answer; that answer becomes the step's `=` line, so the block opens ALREADY RAN with
// the real response — nothing to press, nothing for the agent to remember (his: "could the results
// be piped… automatically?").
export const probeEmbedFor = (row, canRender = true) => {
  if (!canRender || !row || !row.sv || row.sv.verb !== "probe" || !row.sv.project) return null;
  const ns = String(row.sv.project).trim();
  const raw = String(row.sv.target || "").trim().replace(/^['"]|['"]$/g, "");
  // THE CLI'S ARGUMENT SHAPE IS THE CALL'S. An object is one argument (the grammar's shorthand,
  // `ns { … }`); a JSON ARRAY is the positional list — `probe ns '[a, b]'` calls ns(a, b) — so it
  // becomes the call form `ns(a, b)`. Written as one array argument it re-ran as ns([a, b]) and
  // failed (his catch: "I ran it, it broke").
  let args = "";
  if (raw && /^[[{]/.test(raw)) {
    try {
      const v = JSON.parse(raw);
      args = Array.isArray(v) ? `(${v.map((x) => JSON.stringify(x)).join(", ")})` : ` ${JSON.stringify(v)}`;
    } catch {
      args = ` ${raw}`;
    }
  }
  let result = "";
  const out = row.output == null ? "" : String(row.output).trim();
  if (out) {
    const tryJson = (t) => { try { return `\n  = ${JSON.stringify(JSON.parse(t))}`; } catch { return ""; } };
    result = tryJson(out);
    if (!result) {
      // The CLI prints its answer LAST, at column 0, after its own log lines ("ℹ …", "✔ result:").
      // Take the text from the last line that opens a JSON value — a greedy grab from the first
      // bracket swallowed the header's `combine([{…` and never parsed.
      const lines = out.split("\n");
      let start = -1;
      for (let i = lines.length - 1; i >= 0; i -= 1) if (/^[[{]/.test(lines[i])) { start = i; break; }
      if (start >= 0) result = tryJson(lines.slice(start).join("\n"));
    }
  }
  return `:::run{title="probe ${ns}"}\n- ${ns}${args}${result}\n:::`;
};

// A HOOK FIRING, OPENABLE — his ask, 2026-10-08: *"when a hook fires I don't see that, and I
// should. I should be able to click on the hook and see what the description and stuff was, the
// parameters, what it was injected. And the same goes for if a hook points to a job."*
//
// The text exists and was reaching nobody. `HOOKWRAP` strips the pointer out of the transcript so
// the mechanism cannot draw as the human typing — correct, and it left the words visible to no one.
// Hidden from the transcript, available on the row: the same bargain the injected row already made.
//
// AND THE HEADLINE IS THE OUTCOME, NOT THE POINTER. A job that fired and was refused for a missing
// input drew the identical row to one that ran. `given` / `refused` is the first thing on the row
// now, because the row's job is to say what happened.
const HookRow = ({ row }) => {
  const [open, setOpen] = useState(false);
  const isJob = !!row.job;
  const refused = isJob && row.given === false;
  const body = row.text || row.note;
  return (
    <div
      className={`${CLASSNAME}__row ${CLASSNAME}__row--hook${row.work ? ` ${CLASSNAME}__row--hookwork` : ""}${
        isJob ? ` ${CLASSNAME}__row--hookjob` : ""
      }${refused ? ` ${CLASSNAME}__row--hookrefused` : ""}`}
    >
      <div
        role="button"
        tabIndex={0}
        style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap", cursor: body ? "pointer" : "default" }}
        onClick={() => body && setOpen(!open)}
        onKeyDown={(e) => body && (e.key === "Enter" || e.key === " ") && setOpen(!open)}
      >
        <When ts={row.ts} />
        <span className={`${CLASSNAME}__hook-mark`}>⇥</span>
        <span className={`${CLASSNAME}__hook-name`}>{row.name}</span>
        <span className={`${CLASSNAME}__hook-on`}>on {row.on}</span>
        {row.to && <span className={`${CLASSNAME}__hook-to`}>→ {row.to}</span>}
        {isJob && (
          <span className={`${CLASSNAME}__hook-verdict${refused ? ` ${CLASSNAME}__hook-verdict--no` : ""}`}>
            {refused ? `refused — needs ${(row.missing || []).join(", ")}` : "given"}
          </span>
        )}
        {row.work && !isJob && <span className={`${CLASSNAME}__hook-work`}>work</span>}
        {body ? <span className={`${CLASSNAME}__cmd-sign`}>{open ? "▾" : "▸"}</span> : null}
      </div>
      {open && (
        <div className={`${CLASSNAME}__hook-detail`}>
          {/* THE PARAMETERS HE ASKED FOR — the hook's own definition, which until now lived only on
              the profile page, three clicks away from the row that was asking about it. */}
          <div className={`${CLASSNAME}__hook-facts`}>
            {row.cond && <span>when {JSON.stringify(row.cond)}</span>}
            {row.rate && <span>rate {row.rate}</span>}
            {row.inputs && <span>with {Object.entries(row.inputs).map(([k, v]) => `${k}=${v}`).join(", ")}</span>}
            {row.runId && <span>run {row.runId}</span>}
          </div>
          {row.note && <div className={`${CLASSNAME}__hook-note`}>{row.note}</div>}
          {/* WHAT WAS ACTUALLY INJECTED, verbatim — the words the model got, not a paraphrase. */}
          {row.text && <div className={`${CLASSNAME}__injected-body`}>{row.text}</div>}
        </div>
      )}
    </div>
  );
};

// RFC-013 — the injected-context receipt, OPENABLE (his catch: "since when is a log only a bar?
// you click to open it and see what it's about"). Closed it reads like the hook row — the same
// kind of moment, context arriving unasked — and open it shows exactly what was delivered, the
// same text the model saw. Whole header toggles, sign always visible: the feed's own fold rules.
const InjectedRow = ({ row }) => {
  const [open, setOpen] = useState(false);
  return (
    <div className={`${CLASSNAME}__row ${CLASSNAME}__row--hook`}>
      <div
        role="button"
        tabIndex={0}
        style={{ display: "flex", alignItems: "center", gap: 6, cursor: row.text ? "pointer" : "default" }}
        onClick={() => row.text && setOpen(!open)}
        onKeyDown={(e) => row.text && (e.key === "Enter" || e.key === " ") && setOpen(!open)}
      >
        <When ts={row.ts} />
        <span className={`${CLASSNAME}__hook-mark`}>⚡</span>
        <span className={`${CLASSNAME}__hook-name`}>injected context</span>
        <span className={`${CLASSNAME}__hook-on`}>{row.moment}{row.chars ? ` · ${row.chars} chars` : ""}</span>
        {row.text ? <span className={`${CLASSNAME}__cmd-sign`}>{open ? "▾" : "▸"}</span> : null}
      </div>
      {open && row.text && <div className={`${CLASSNAME}__injected-body`}>{row.text}</div>}
    </div>
  );
};

// RFC-071 — A MEMBERSHIP DELIVERY, OPENABLE. A reply in a thread you are on, or a document you
// are a member of changing, arrives as a turn — and it used to be a flat "✉ message landed…" line
// cut at 140 characters, which is a receipt you can read and nothing else. His: *"why isn't that
// thread log expandable like most logs so you can see details?"*
//
// Closed: who moved what. Open: the thread, the whole delivered text, and the document itself —
// one press opens the file in the navigator, because the first thing you want after reading that a
// thread moved is to be IN it.
const LandedDocRow = ({ row }) => {
  const [open, setOpen] = useState(false);
  const file = String(row.path || "").split("/").pop();
  const openDoc = (e) => {
    e.stopPropagation();
    window.dispatchEvent(
      new CustomEvent("sv:openFileInNav", {
        detail: { projectCode: row.project || undefined, path: row.path },
      }),
    );
  };
  return (
    <div className={`${CLASSNAME}__row ${CLASSNAME}__row--hook`}>
      <div
        role="button"
        tabIndex={0}
        style={{ display: "flex", alignItems: "center", gap: 6, cursor: "pointer" }}
        onClick={() => setOpen(!open)}
        onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && setOpen(!open)}
      >
        <When ts={row.ts} />
        {/* A MERGED LANDING GREW RATHER THAN ARRIVED — the harness folded it into a delivery still
            sitting unread instead of spending a second turn. Two rows that look identical would put
            the interruptions back in the log after we removed them from the session, so the mark
            and the words both say which happened: ✉ is post, ⊕ is "the one you have got bigger". */}
        <span className={`${CLASSNAME}__hook-mark`}>{row.merged ? "⊕" : "✉"}</span>
        <span className={`${CLASSNAME}__hook-name`}>
          {row.merged
            ? `${row.thread ? `thread ${row.thread}` : "this document"} folded into a delivery you had not read`
            : row.thread
              ? `thread ${row.thread} moved`
              : "document updated"}
        </span>
        <span className={`${CLASSNAME}__hook-on`}>
          {file}
          {row.from ? ` · by ${row.from}` : ""}
        </span>
        <span className={`${CLASSNAME}__cmd-sign`}>{open ? "▾" : "▸"}</span>
      </div>
      {open && (
        <div className={`${CLASSNAME}__injected-body`}>
          <div>
            <button type="button" className={`${CLASSNAME}__tool-btn`} onClick={openDoc} title="open this document">
              {row.project ? `${row.project}:` : ""}
              {row.path}
            </button>
          </div>
          {row.summary ? <div>{row.summary}</div> : null}
          {row.text ? <div>{row.text}</div> : null}
        </div>
      )}
    </div>
  );
};

const ToolRow = ({ row, renderText = null }) => {
  const [open, setOpen] = useState(false);
  // THE FILE IS IN THE ROW. His ask, verbatim: the rows that show what an agent ran carry buttons
  // that POINT at things — open, diff — when expanding the row should SHOW them, embedded, the
  // same blocks the chat already renders. So an opened row draws the file it read (at the lines
  // it read), or the diff of what it wrote, right here. The button and the fold stay exactly as
  // they were — this is added under them, not instead of them.
  // A PROBE OPENS AS A RUN. `systemview probe Service.Module.method '{…}'` is a method call, and
  // the document vocabulary already has the block for one: an ad-hoc `:::run` with that step. So
  // an opened probe row draws the same runnable the docs use — press play, see the live result —
  // instead of a "code" button pointed at a namespace as if it were a file (his catch).
  const probeEmbed = probeEmbedFor(row, !!renderText);
  // A TOOL THAT FILED A PICTURE OPENS AS THE PICTURE. His ruling, 2026-10-19: *"if I expand the
  // log, it's supposed to show me the screenshot"* — and then, seeing the block in a message:
  // *"obviously that means you can use the same markdown in the logs."* So it does, literally —
  // `::image` is the renderer, not a second one written for this row, which is the same reason a
  // read opens as `::file` and a write as `::diff`.
  //
  // The path is taken from the row's own `image` when the feed carried one, and otherwise read
  // out of the output text. Both, because the row field is the better answer and the text is the
  // one that cannot be lost between the harness, the hub and here.
  const shotPath = (() => {
    if (row.image) return String(row.image);
    const m = String(row.output == null ? "" : row.output).match(/(\/[^\s"']+\.(?:png|jpe?g|gif|webp))/i);
    return m ? m[1] : null;
  })();
  const embed =
    probeEmbed ||
    (renderText && shotPath ? `::image[${shotPath}]` : null) ||
    (renderText && row.rel
      ? row.wrote
        ? `::diff[${row.rel}]`
        : `::file[${row.rel}${row.span ? `#L${row.span}` : ""}]`
      : null);
  // THE DOOR CARRIES THE ADDRESS. This dispatched `{ path }` alone — an ABSOLUTE path with no
  // project behind it — and the code pane, which is addressed by project + repo path, opened
  // nothing. His report: *"I clicked on diff and that shit didn't bring up the diffs."* Now it
  // sends the project the event was stamped with, the repo-relative path, the lines a Read looked
  // at, and asks for the diff side when the row wrote.
  const openPath = (e) => {
    e.stopPropagation();
    // "diff" MEANS THE DIFF. The pane treats diff as a MODE it remembers (`sv.diffMode`), not a
    // per-open flag — so the diff button turns the mode on before it opens the file, and the pane
    // comes up side-by-side instead of on the plain source with a toggle you then have to find.
    if (row.wrote) { try { localStorage.setItem("sv.diffMode", "true"); } catch {} }
    const lines = row.span ? row.span.split("-").map(Number) : null;
    window.dispatchEvent(
      new CustomEvent("sv:openFileInNav", {
        detail: {
          projectCode: row.project || undefined,
          path: row.rel || row.path,
          lines: lines && lines[0] ? (lines.length > 1 ? lines : [lines[0], lines[0]]) : undefined,
          // The nav's two sides of the index are "staged" and "unstaged"; a write lands unstaged.
          ...(row.wrote ? { side: "unstaged" } : {}),
        },
      }),
    );
  };
  const cmd = row.input && typeof row.input.command === "string" ? row.input.command : null;
  const out = row.output == null ? "" : String(row.output);
  // The rest of the arguments, minus the one already shown as the command — printing `command`
  // twice under its own heading is the "Edit edited CodePane.js" mistake in another costume.
  const rest = (() => {
    if (!row.input || typeof row.input !== "object") return null;
    const { command, ...others } = row.input;
    return Object.keys(others).length ? others : null;
  })();

  const has = !!(cmd || out || rest || embed);

  return (
    <div
      className={`${CLASSNAME}__row ${CLASSNAME}__row--tool ${CLASSNAME}__row--${row.state}${
        row.sv ? ` ${CLASSNAME}__row--sv` : ""
      }${row.mcp ? ` ${CLASSNAME}__row--mcp` : ""}${has ? ` ${CLASSNAME}__row--can` : ""}`}
      // THE WHOLE ROW IS THE HANDLE, not the words on it — his: "why do you got to actually click
      // on the name in the row?" A click anywhere on the row that isn't a button toggles it; the
      // open/diff button stops its own click so it never doubles as a fold.
      onClick={(e) => { if (has && !open && !e.target.closest("button, a, .agent-wb__tool-body")) setOpen(true); }}
    >
      <div
        className={`${CLASSNAME}__tool-head${has ? ` ${CLASSNAME}__tool-head--can` : ""}`}
        role={has ? "button" : undefined}
        tabIndex={has ? 0 : undefined}
        onClick={(e) => { if (has) { e.stopPropagation(); setOpen(!open); } }}
        onKeyDown={(e) => has && (e.key === "Enter" || e.key === " ") && setOpen(!open)}
      >
        {row.sv ? (
          // Its own mark instead of a state dot: this is SystemView doing something, and which
          // something is the first thing worth knowing.
          <span className={`${CLASSNAME}__sv-icon`}>{row.sv.icon}</span>
        ) : row.skill ? (
          // The same diamond the profile marks a skill with, so the two surfaces agree on sight.
          <span className={`${CLASSNAME}__sv-icon`}>◈</span>
        ) : (
          <span className={`${CLASSNAME}__dot ${CLASSNAME}__dot--${row.state}`} />
        )}
        {/* THE SUMMARY IS THE WHOLE LINE. Printing the tool name beside it read "Edit edited
            CodePane.js" — the same thing twice, in a feed whose only job is to be skimmable. */}
        <span className={`${CLASSNAME}__tool-sum`}>
          {/* SAY THE TOOL'S NAME. A bash row reads "run …"; a SystemView row read only its summary,
              so it looked like any other command in the feed — his catch: *"why doesn't mine just
              say systemview as the first word, so you know it's a SystemView command."* */}
          {(row.sv || row.mcp || row.skill || row.tool === "Bash") && (
            <span
              className={`${CLASSNAME}__sv-kind${
                row.sv
                  ? ""
                  : row.skill
                  ? ` ${CLASSNAME}__sv-kind--skill`
                  : row.mcp
                  ? ` ${CLASSNAME}__sv-kind--mcp ${CLASSNAME}__sv-kind--mcp-${row.mcp.server}`
                  : ` ${CLASSNAME}__sv-kind--sh`
              }`}
            >
              {row.sv ? "systemview" : row.skill ? "skill" : row.mcp ? row.mcp.server : "bash"}
            </span>
          )}
          {row.summary}
          {/* A SystemView row's summary IS the whole command line now — nothing to add beside it. */}
        </span>
        {/* THE PATH IS A DOOR. An agent editing a file is the moment you most want to look at the
            file, and the diff for it is already a click away in the codebase panel. */}
        {row.path && (
          <button type="button" className={`${CLASSNAME}__tool-open`} title={`Open ${row.path}`} onClick={openPath}>
            {row.wrote ? "diff" : "open"}
          </button>
        )}
        {/* SAY WHAT'S INSIDE. A bare "+" gave no hint that a file or a diff was waiting under the
            row — his: "there should be some sort of indication if there's an embedded thing." The
            fold names it: `file ▾` / `diff ▾`, and folds back to "−" when open. */}
        {has && (
          <span
            className={`${CLASSNAME}__tool-fold${embed ? ` ${CLASSNAME}__tool-fold--embed` : ""}`}
            title={open ? "Fold it away" : embed ? (row.wrote ? "Show the diff here" : "Show the file here") : "Show what it ran and what came back"}
          >
            {open ? "−" : embed ? (row.wrote ? "diff ▾" : "file ▾") : "+"}
          </span>
        )}
      </div>
      {open && has && (
        <div className={`${CLASSNAME}__tool-body`}>
          {/* THE BLOCK FIRST. What the row is about — the file, the diff, the run with its result —
              goes on top; the exact command and its raw output sit under it (his order). */}
          {embed && <div className={`${CLASSNAME}__tool-embed`}>{renderText(embed)}</div>}
          {/* The command reads like a prompt, because that is what it is. */}
          {cmd && (
            <Block kind="cmd">
              {cmd.split("\n").map((line, i) => (
                <div key={i} className={`${CLASSNAME}__cmd-line`}>
                  <span className={`${CLASSNAME}__cmd-sign`}>{i === 0 ? "$" : " "}</span>
                  {line}
                </div>
              ))}
            </Block>
          )}
          {rest && (row.mcp
            ? <HiJson value={rest} />
            : <Block kind="args">{JSON.stringify(rest, null, 2)}</Block>)}
          {/* STILL RUNNING is a state worth drawing — a command with no output yet is not a command
              that printed nothing. */}
          {!out && row.state === "running" && <div className={`${CLASSNAME}__tool-wait`}>running…</div>}
          {/* OUR OWN TOOLS SPEAK HUMAN — the words come out of the tool already readable (his
              rule: "they should come out nice and human readable — those are the words"), so
              they render as prose, not as stdout in a mono block. Bash keeps the mono block;
              it earned it. */}
          {out &&
            (() => {
              const data = row.mcp && parseMcpResult(row.mcp, out);
              if (data) return <McpTable data={data} />;
              // a test run carrying its handle opens as the REAL test display, results in hand
              const runId = row.sv && row.sv.verb === "test" ? (String(out).match(/^run: (\S+)$/m) || [])[1] : null;
              if (runId) return <TestRunEmbed project={row.sv.project} runId={runId} output={out} failed={row.state === "failed"} />;
              return <Block kind={row.state === "failed" ? "err" : "out"}>{out}</Block>;
            })()}
        </div>
      )}
    </div>
  );
};

// A LONG MESSAGE DOES NOT GET TO OWN THE WHOLE CHAT — but only HIS. His correction once he saw it
// applied to both sides: *"that's for my long ass chat. Your messages should be shown. Sometimes I
// dump long messages."* He dumps context; the answer is the thing he came for, and folding it away
// hides the reply behind a click. So the fold rides `mine` and nothing else. The
// fold is MEASURED, not guessed from character count: a code block and a paragraph of the same
// length are nowhere near the same height, so only a body that genuinely runs past the line gets a
// control. Everything short stays exactly as it was — no button, no chrome, no change.
// OUR TOOLS' RESULTS ARE DATA, AND DATA GETS A TABLE — his correction after two rounds of
// prettier text: "we're in a UI." One row per hit: match, note, where; the ROW is the expander
// (the whole row is the handle, same as the tool rows) and its body opens beneath it. The pointer
// is a door: a `<pc>:path` dispatches the same open the codebase rows use. Applies ACROSS THE
// BOARD — every harness tool renders as UI, and only a payload that fails its own contract falls
// back to the raw block, so pretty never loses data.
// loadService — the summary always shown, the METHODS collapsed under it, expandable to a table
// (his: "you can make the methods show, but you have to expand — table of data, human readable").
const LoadedTable = ({ data }) => {
  const [open, setOpen] = useState(false);
  const has = data.methods && data.methods.length;
  return (
    <div className={`${CLASSNAME}__mcp-loaded`}>
      <div
        className={`${CLASSNAME}__mcp-noteline${has ? ` ${CLASSNAME}__mcp-noteline--can` : ""}`}
        onClick={() => has && setOpen(!open)}
      >
        <span className={`${CLASSNAME}__mcp-noteline-label`}>attached</span>
        <span className={`${CLASSNAME}__mcp-noteline-subject`}>{data.subject}</span>
        <span className={`${CLASSNAME}__mcp-noteline-detail`}>{data.detail}</span>
        {has ? <span className={`${CLASSNAME}__mcp-caret`}>{open ? "−" : "+"}</span> : null}
      </div>
      {open && has && (
        <table className={`${CLASSNAME}__mcp-table`}>
          <thead><tr><th>method</th><th>schema</th></tr></thead>
          <tbody>
            {data.methods.map((m) => (
              <tr key={m.namespace} className={`${CLASSNAME}__mcp-tr`}>
                <td className={`${CLASSNAME}__mcp-title`}>{m.namespace}</td>
                <td className={`${CLASSNAME}__mcp-status--${m.schema ? "on" : "off"}`}>{m.schema ? "schema" : "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

const McpTable = ({ data }) => {
  // COLLAPSED BY DEFAULT, INDEPENDENTLY EXPANDABLE — his fix on both counts. The first version
  // was a single-open accordion (one openRow), so opening a row folded whichever was open — "they
  // switch expansion." A Set of OPEN rows, default empty, means each row toggles on its own and
  // any number can be open at once.
  const [open, setOpen] = useState(() => new Set());
  if (data.kind === "call")
    return (
      <div className={`${CLASSNAME}__mcp-call`}>
        <div className={`${CLASSNAME}__mcp-call-head${data.status >= 400 ? ` ${CLASSNAME}__mcp-call-head--bad` : ""}`}>
          <code>{data.namespace}</code> returned <b>{data.status}</b>
          {data.message ? <span> — {data.message}</span> : null}
        </div>
        <pre className={`${CLASSNAME}__blk ${CLASSNAME}__mcp-json${data.status >= 400 ? ` ${CLASSNAME}__mcp-json--bad` : ""}`}>{data.json}</pre>
      </div>
    );
  if (data.kind === "services")
    return (
      <table className={`${CLASSNAME}__mcp-table`}>
        <thead><tr><th>service</th><th>status</th><th>where</th></tr></thead>
        <tbody>
          {data.rows.map((r) => (
            <tr key={r.name} className={`${CLASSNAME}__mcp-tr`}>
              <td className={`${CLASSNAME}__mcp-title`}>{r.name}</td>
              <td className={`${CLASSNAME}__mcp-status--${/attach/i.test(r.status) ? "on" : "off"}`}>{r.status}</td>
              <td className={`${CLASSNAME}__mcp-where`}>{r.detail}</td>
            </tr>
          ))}
        </tbody>
      </table>
    );
  if (data.kind === "loaded")
    return <LoadedTable data={data} />;
  if (data.kind === "note-line")
    return (
      <div className={`${CLASSNAME}__mcp-noteline`}>
        <span className={`${CLASSNAME}__mcp-noteline-label`}>{data.label}</span>
        <span className={`${CLASSNAME}__mcp-noteline-subject`}>{data.subject}</span>
        <span className={`${CLASSNAME}__mcp-noteline-detail`}>{data.detail}</span>
        {data.warn && <span className={`${CLASSNAME}__mcp-noteline-warn`}>{data.warn}</span>}
      </div>
    );
  // TWO SHELVES, BOTH VISIBLE — notes then documentation, the same divide the tool's own text
  // draws. Not tabs: the bug this fixes was one half being invisible, and a tab would hide it
  // again behind a click, just politely.
  if (data.kind === "context")
    return (
      <div className={`${CLASSNAME}__ctx`}>
        {data.rows.length > 0 && (
          <>
            <div className={`${CLASSNAME}__ctx-shelf`}>notes · {data.rows.length}</div>
            <McpTable data={{ kind: "notes", rows: data.rows }} />
          </>
        )}
        {data.docs.length > 0 && (
          <>
            <div className={`${CLASSNAME}__ctx-shelf`}>documentation · {data.docs.length}</div>
            <McpTable data={{ kind: "docs", rows: data.docs }} />
          </>
        )}
      </div>
    );
  const withBody = data.rows.map((r, i) => (r.body ? i : -1)).filter((i) => i >= 0);
  const allOpen = withBody.length > 0 && withBody.every((i) => open.has(i));
  return (
    <table className={`${CLASSNAME}__mcp-table`}>
      <thead>
        <tr>
          <th>match</th>
          <th>{data.kind === "docs" ? "section" : "note"}</th>
          <th>{data.kind === "docs" ? "file · corpus" : "from"}</th>
          {/* EXPAND ALL / COLLAPSE ALL — his ask, at the top. One press opens every row that has a
              body or folds them all; individual rows still toggle on their own underneath it. */}
          <th className={`${CLASSNAME}__mcp-allth`}>
            {withBody.length > 1 && (
              <button
                type="button"
                className={`${CLASSNAME}__mcp-all`}
                title={allOpen ? "Collapse all" : "Expand all"}
                onClick={() => setOpen(allOpen ? new Set() : new Set(withBody))}
              >
                {allOpen ? "−" : "+"}
              </button>
            )}
          </th>
        </tr>
      </thead>
      <tbody>
        {data.rows.map((r, i) => (
          <React.Fragment key={i}>
            <tr
              className={`${CLASSNAME}__mcp-tr${open.has(i) ? ` ${CLASSNAME}__mcp-tr--open` : ""}`}
              onClick={() =>
                setOpen((o) => {
                  const n = new Set(o);
                  n.has(i) ? n.delete(i) : n.add(i);
                  return n;
                })
              }
            >
              <td className={`${CLASSNAME}__mcp-score`}>{r.score}</td>
              <td className={`${CLASSNAME}__mcp-title`}>{r.title}</td>
              <td className={`${CLASSNAME}__mcp-where`}>{r.corpus ? `${r.where} · ${r.corpus}` : r.where || ""}</td>
              <td className={`${CLASSNAME}__mcp-caret`}>{r.body ? (open.has(i) ? "−" : "+") : ""}</td>
            </tr>
            {open.has(i) && r.body && (
              <tr className={`${CLASSNAME}__mcp-detail`}>
                <td colSpan={4}>
                  {r.body}
                  {/* the note's id — what remember(id=) and forget() take, so the exact block
                      is addressable from here too */}
                  {r.id && <span className={`${CLASSNAME}__mcp-id`}>id {r.id}</span>}
                  {r.pointer && (
                    <button
                      type="button"
                      className={`${CLASSNAME}__mcp-ptr`}
                      onClick={(e) => {
                        e.stopPropagation();
                        const mm = /^([a-zA-Z0-9._-]+):(.+)$/.exec(r.pointer);
                        if (mm)
                          window.dispatchEvent(new CustomEvent("sv:openFileInNav", { detail: { projectCode: mm[1], path: mm[2] } }));
                      }}
                    >
                      → {r.pointer}
                    </button>
                  )}
                </td>
              </tr>
            )}
          </React.Fragment>
        ))}
      </tbody>
    </table>
  );
};

const CLAMP = 260;

const Said = ({ row, render, clamp = false }) => {
  const [open, setOpen] = useState(false);
  const [over, setOver] = useState(false);
  const ref = useRef(null);
  // Re-measured on every text change, because a streaming answer crosses the line mid-flight and a
  // fold that only checked once would either never appear or appear and then be wrong.
  useLayoutEffect(() => {
    const el = ref.current;
    if (el) setOver(clamp && el.scrollHeight > CLAMP + 24);
  }, [row.text, clamp]);
  const body = render ? render(row.text) : row.text;
  return (
    <>
      <div
        ref={ref}
        className={`${CLASSNAME}__said${over && !open ? ` ${CLASSNAME}__said--clamped` : ""}`}
        style={over && !open ? { maxHeight: CLAMP } : undefined}
      >
        {body}
      </div>
      {over && (
        <button type="button" className={`${CLASSNAME}__more`} onClick={() => setOpen((v) => !v)}>
          {open ? "See less" : "See more"}
        </button>
      )}
    </>
  );
};

// WHAT HE ATTACHED, on the turn he attached it to. Thumbnails only — the full bytes went to the
// model and were never kept here. Its own component because it holds state: the zoom. `Feed` is a
// map, not a component, so a hook cannot live there.
const Attachments = ({ row }) => {
  const [zoom, setZoom] = useState(null);
  const ims = row.images || [];
  if (!ims.length) return null;
  return (
    <div className={`${CLASSNAME}__shots`}>
      {ims.map((im, n) => (
        <button
          type="button"
          key={`${row.key}-im${n}`}
          className={`${CLASSNAME}__shot`}
          title={im.name || "image"}
          // ZOOM, NEVER NAVIGATE. This opened the thumbnail in a new view — his: *"the images I
          // send navigate me to a page instead of using the magnifying glass that makes me see it
          // closer."* Leaving the conversation to read a picture that is already in it is the
          // opposite of looking closer, and it is the same lightbox the markdown image block uses,
          // so both halves of a conversation enlarge the same way.
          onClick={(e) => { e.stopPropagation(); if (im.thumb) setZoom(im.thumb); }}
        >
          {im.thumb ? <img src={im.thumb} alt={im.name || "attachment"} /> : <span>{im.name || "image"}</span>}
        </button>
      ))}
      {zoom && (
        <div className="md-image__lightbox" onClick={() => setZoom(null)}>
          <img src={zoom} alt={row.name || "zoom"} />
        </div>
      )}
    </div>
  );
};

const Feed = ({ rows, answered = {}, onAnswer = null, renderText = null }) =>
  rows.map((r) =>
    r.kind === "tool" ? (
      r.xsend ? <SentRow key={r.key} row={r} /> : <ToolRow key={r.key} row={r} renderText={renderText} />
    ) : r.kind === "think" ? (
      // Reasoning is quiet by design: it is context for what it did, not the thing it did.
      <div key={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__row--think`}>{r.text}</div>
    ) : r.kind === "ask" ? (
      <div
        key={r.key}
        className={`${CLASSNAME}__row ${CLASSNAME}__row--ask${
          answered[r.id] === undefined ? "" : ` ${CLASSNAME}__row--answered`
        }`}
      >
        <span className={`${CLASSNAME}__ask-title`}>{r.title}</span>
        {answered[r.id] === undefined ? (
          <>
            <button type="button" className={`${CLASSNAME}__ask-yes`} onClick={() => onAnswer && onAnswer(r.id, true)}>allow</button>
            <button type="button" className={`${CLASSNAME}__ask-no`} onClick={() => onAnswer && onAnswer(r.id, false)}>deny</button>
          </>
        ) : (
          <span className={`${CLASSNAME}__ask-was`}>{answered[r.id] ? "allowed" : "denied"}</span>
        )}
      </div>
    ) : r.kind === "done" ? (
      <div key={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__row--done`}>
        {`${r.ok ? "done" : "stopped"}${r.turns ? ` · ${r.turns} turns` : ""}${
          r.durationMs ? ` · ${Math.round(r.durationMs / 1000)}s` : ""
        }${money(r.costUsd) ? ` · ${money(r.costUsd)}` : ""}`}
      </div>
    ) : r.kind === "mine" && r.as === "cmd" ? (
      // A COMMAND'S REPORT IS A LOG LINE, NOT A CHAT BUBBLE (his call: one row, and the visitor
      // costume's hash colour was wrong for a machine). "cmd" is a reserved identity — the row
      // wears the :::cmd block's own slate, the name sits inline in the prompt green, and the text
      // stays plain: a one-line receipt, never a paragraph.
      <div key={r.key} data-row={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__cmdrow ${CLASSNAME}__cmdrow--${receiptTone(r.text)}`}>
        <When ts={r.ts} />
        <span className={`${CLASSNAME}__cmdrow-name`}>cmd</span>
        <span className={`${CLASSNAME}__cmdrow-text`}>{r.text}</span>
      </div>
    ) : r.kind === "mine" ? (
      // His own turns, so a resumed conversation reads like a conversation and not a monologue.
      <div
        key={r.key}
        // The address a "spoke" chip jumps to. A visitor's turn is the one row you go looking for
        // after the fact — "who was that and what did they say" — so it has to be addressable.
        data-row={r.key}
        className={`${CLASSNAME}__row ${CLASSNAME}__row--mine${r.as ? ` ${CLASSNAME}__row--visit` : ""}`}
        style={visStyle(r.as)}
      >
        {/* WHO JUMPED IN, always on screen. An agent reaching into this conversation through the
            CLI must never read as the human — his standing rule for visiting, carried over from the
            room: you can always see who is in whose chat. */}
        <When ts={r.ts} />
        {r.as && (
          <span className={`${CLASSNAME}__visitor`} style={visStyle(r.as)}>
            {r.as}
          </span>
        )}
        <Attachments row={r} />
        <Said row={r} render={renderText} clamp={!r.as} />
      </div>
    ) : r.kind === "hook" ? (
      // A HOOK FIRING IS A THING THAT HAPPENED, so it reads like every other thing that happened —
      // a row in the feed's existing vocabulary, never raw injected text dumped into the chat.
      // The chain has to be traceable end to end: this row is the first link (hook fired), the
      // skill load is the second, and what the agent did next is the third. It OPENS for the rest.
      <HookRow key={r.key} row={r} />
    ) : r.kind === "injected" ? (
      <InjectedRow key={r.key} row={r} />
    ) : r.kind === "cmdret" ? (
      // A TERMINAL COMMAND'S RECEIPT — /usage, /model, whatever the host ran and answered itself.
      // His ask: *"make a nice display for commands like that that return — it should be showing
      // nice bars."* The command reads like the tool rows' header; the printout keeps its lines,
      // and any line that states a percentage draws it as a thin bar under the words, in the
      // meter's own colour language (calm, then amber past 75, red past 90) — the same thresholds
      // the context ruler uses, so a number that means "getting full" looks like getting full.
      <div key={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__row--cmdret`}>
        <div className={`${CLASSNAME}__cmdret-head`}>
          <span className={`${CLASSNAME}__cmdret-name`}>{r.name || "command"}</span>
          {r.args ? <span className={`${CLASSNAME}__cmdret-args`}>{r.args}</span> : null}
        </div>
        {r.out ? (
          <div className={`${CLASSNAME}__cmdret-out`}>
            {r.out.split("\n").map((line, i) => {
              const m = line.match(/(\d{1,3})%/);
              const pct = m ? Math.min(100, Number(m[1])) : null;
              return line.trim() ? (
                <div key={i} className={`${CLASSNAME}__cmdret-line`}>
                  <span className={`${CLASSNAME}__cmdret-text`}>{line}</span>
                  {pct !== null && (
                    <span className={`${CLASSNAME}__cmdret-bar`}>
                      <span
                        className={`${CLASSNAME}__cmdret-bar-fill${
                          pct >= 90
                            ? ` ${CLASSNAME}__cmdret-bar-fill--due`
                            : pct >= 75
                            ? ` ${CLASSNAME}__cmdret-bar-fill--warn`
                            : ""
                        }`}
                        style={{ width: `${pct}%` }}
                      />
                    </span>
                  )}
                </div>
              ) : (
                <div key={i} className={`${CLASSNAME}__cmdret-gap`} />
              );
            })}
          </div>
        ) : null}
      </div>
    ) : r.kind === "landed-doc" ? (
      <LandedDocRow key={r.key} row={r} />
    ) : r.kind === "note" ? (
      // A compaction — the moment the conversation he is reading lost its middle. It is an event,
      // not a silence, so it says so. The receipt gets its own mark and colour, matching the browser
      // panel's line exactly (⦿, green): he watches both windows at once, and a moment that reads
      // as two different things in two views is worse than a moment shown in only one.
      <div
        key={r.key}
        className={`${CLASSNAME}__row ${CLASSNAME}__row--note${
          r.before !== undefined ? ` ${CLASSNAME}__row--compaction` : ""
        }${r.model ? ` ${CLASSNAME}__row--model` : ""}`}
      >
        {(r.before !== undefined || r.model) && <span className={`${CLASSNAME}__note-mark`}>⦿</span>}
        {r.text}
      </div>
    ) : r.kind === "seam" ? (
      <div key={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__row--seam`}>{r.text}</div>
    ) : r.kind === "error" ? (
      <div key={r.key} className={`${CLASSNAME}__row ${CLASSNAME}__row--error`}>{r.text}</div>
    ) : (
      <div
        key={r.key}
        data-row={r.key}
        className={`${CLASSNAME}__row ${CLASSNAME}__row--say${r.toRoom ? ` ${CLASSNAME}__row--toroom` : ""}`}
      >
        {/* SENT, NOT SAID. A message this agent put in its own room arrives here through `showSaid`
            — shown, never fed back, because feeding an agent its own words has it answering itself.
            Drawn as plain speech it was indistinguishable from a sentence in the session, which is
            exactly what Odion reported: the agent appears, the message doesn't. The mark says where
            it went. (systemlynx traced this from the other side: a room's own agent carries no `as`
            field, correctly, so there was nothing left to key on by the time it got here.) */}
        {r.toRoom && (
          <span className={`${CLASSNAME}__toroom`} title={`sent to the ${typeof r.toRoom === "string" ? r.toRoom : "project"} room`}>
            ↗ room
          </span>
        )}
        {r.settled && <When ts={r.ts} />}
        <Said row={r} render={renderText} />
        {r.settled && <SpeakReply text={r.text} rowKey={r.key} ts={r.ts} />}
      </div>
    ),
  );

export { money };
export default Feed;
